adcs_quat_t unit, candidate;
adcs_status_t st;
double dot, absdot, pre;

if (sample == NULL) {
    if (accepted != NULL)
        *accepted = (adcs_quat_t){1, 0, 0, 0};
    if (separation_rad != NULL)
        *separation_rad = (double)INFINITY;
    return ADCS_E_NULL;
}
if ((accepted == NULL) || (separation_rad == NULL))
    return ADCS_E_NULL;

st = adcs_quat_normalize(sample, &unit);
if (st != ADCS_OK) {
    *accepted = (adcs_quat_t){1, 0, 0, 0};
    *separation_rad = (double)INFINITY;
    return ADCS_E_DEGENERATE;
}

if (!qc_state.initialized) {
    if (unit.w < 0.0) {
        unit.w = -unit.w;
        unit.x = -unit.x;
        unit.y = -unit.y;
        unit.z = -unit.z;
    }
    *accepted = unit;
    *separation_rad = 0.0;
    qc_state.previous = unit;
    qc_state.initialized = 1;
    return ADCS_OK;
}

pre = unit.w * qc_state.previous.w + unit.x * qc_state.previous.x +
      unit.y * qc_state.previous.y + unit.z * qc_state.previous.z;
candidate = unit;
if (pre < 0.0) {
    candidate.w = -candidate.w;
    candidate.x = -candidate.x;
    candidate.y = -candidate.y;
    candidate.z = -candidate.z;
}
dot = candidate.w * qc_state.previous.w + candidate.x * qc_state.previous.x +
      candidate.y * qc_state.previous.y + candidate.z * qc_state.previous.z;
absdot = fabs(dot);
if (absdot > 1.0)
    absdot = 1.0;
*separation_rad = 2.0 * acos(absdot);
*accepted = candidate;
qc_state.previous = candidate;
return ADCS_OK;

