adcs_quat_t aligned;
double dot;
double sep;

if (accepted == NULL || separation_rad == NULL) {
    return ADCS_E_NULL;
}

if (sample == NULL) {
    *accepted = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    *separation_rad = INFINITY;
    return ADCS_E_NULL;
}

if (adcs_quat_normalize(sample, &q) != ADCS_OK) {
    *accepted = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    *separation_rad = INFINITY;
    return ADCS_E_DEGENERATE;
}

if (!qc_state.initialized) {
    if (q.w < 0.0) {
        q.w = -q.w;
        q.x = -q.x;
        q.y = -q.y;
        q.z = -q.z;
    }
    *accepted = q;
    *separation_rad = 0.0;
    qc_state.previous = q;
    qc_state.initialized = 1;
    return ADCS_OK;
}

dot = q.w * qc_state.previous.w + q.x * qc_state.previous.x
    + q.y * qc_state.previous.y + q.z * qc_state.previous.z;
if (dot < 0.0) {
    aligned.w = -q.w;
    aligned.x = -q.x;
    aligned.y = -q.y;
    aligned.z = -q.z;
} else {
    aligned = q;
}

sep = adcs_quat_abs_dot(&aligned, &qc_state.previous);
if (sep > 1.0) {
    sep = 1.0;
} else if (sep < -1.0) {
    sep = -1.0;
}
*separation_rad = 2.0 * acos(sep);

*accepted = aligned;
qc_state.previous = aligned;
return ADCS_OK;

